def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue

        parts = line.split(",")
        if len(parts) != 3:
            raise ValueError(f"invalid log line {line_number}: expected 3 fields (line {line_number})")

        id_, day_text, flagged_text = (part.strip() for part in parts)

        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"invalid day on line {line_number}") from exc

        if flagged_text == "1":
            flagged = True
        elif flagged_text == "0":
            flagged = False
        elif flagged_text == "":
            flagged = None
        else:
            raise ValueError(f"invalid flagged value on line {line_number}")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out



def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for event in events:
        seen[event["id"]] = event
    return sorted(seen.values(), key=lambda event: (event["day"], event["id"]))



def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        if event.get("flagged") is True and start_day <= event["day"] <= end_day:
            counts[event["day"] - start_day] += 1
    return counts
