{"file_path":"tests/test_metrics.py","content":"from safety_evals import (
    daily_flag_counts,
    dedupe_transcripts,
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    monitor_summary,
    parse_transcript_log,
    pooled_flag_rate,
    top_flagged_groups,
)



def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5



def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 1 / 3



def test_monitor_flag_rate_empty_list_is_zero():
    assert monitor_flag_rate([]) == 0.0



def test_pooled_flag_rate_is_weighted_by_transcript_count():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5



def test_flags_in_window_follows_spec_examples():
    assert flags_in_window([1, 2, 3, 4], 0) == 0
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3, 4], 10) == 10



def test_parse_transcript_log_parses_and_skips_specified_lines():
    lines = [
        "   ",
        " # comment",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]



def test_parse_transcript_log_error_reports_original_line_number():
    try:
        parse_transcript_log(["", "# comment", "x1,not-a-day,1"])
    except ValueError as exc:
        assert "line 3" in str(exc)
    else:
        raise AssertionError("expected ValueError")



def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    events = [
        {"id": "b", "day": 3, "flagged": True},
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 1, "flagged": False},
        {"id": "a", "day": 4, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "b", "day": 1, "flagged": False},
        {"id": "a", "day": 4, "flagged": True},
    ]



def test_daily_flag_counts_uses_inclusive_range_and_ignores_outside_days():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
        {"id": "e", "day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []



def test_monitor_summary_matches_spec():
    groups = {
        "g1": [
            {"id": "a", "day": 1, "flagged": True},
            {"id": "b", "day": 2, "flagged": False},
        ],
        "g2": [
            {"id": "c", "day": 4, "flagged": True},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}



def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "beta": [{"flagged": True}, {"flagged": False}],
        "alpha": [{"flagged": True}, {"flagged": False}],
        "gamma": [{"flagged": True}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["gamma", "alpha", "beta"]



def test_flag_rate_by_group_in_name_order_with_none_for_empty_groups():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [],
        "c": [{"flagged": False}],
    }
    assert flag_rate_by_group(groups) == {"a": None, "b": 0.5, "c": 0.0}



def test_longest_flag_streak_resets_after_zero():
    assert longest_flag_streak([1, 2, 0, 3, 4, 5, 0, 1]) == 3
    assert longest_flag_streak([]) == 0
